import json
import os


def load_history():
    if not os.path.exists("sohbet.json"):
        return []
    with open("sohbet.json") as f:
        return json.load(f)


def log_message(sender, text):
    history = load_history()
    history.append({"sender": sender, "text": text})
    with open("sohbet.json", "w") as f:
        json.dump(history, f)
    return len(history)

