        json.dump(grades, f)


def load_grades():
    if not os.path.exists("notlar.json"):
        return {}
    with open("notlar.json") as f:
        return json.load(f)


def add_grade(lesson, grade):
    grades = load_grades()
    grades[lesson] = grade
    save_grades(grades)
